function Component({ config = {} }) {
  const [expandedNodes, setExpandedNodes] = React.useState(new Set(['ceo', 'cto', 'cfo', 'coo']));

  const showPhotos = config?.showPhotos !== false;
  const showDepartments = config?.showDepartments !== false;
  const expandAllDefault = config?.expandAllDefault !== false;
  const backgroundColor = config?.backgroundColor || "#FFFFFF";
  const cardBackgroundColor = config?.cardBackgroundColor || "#F8F9FA";
  const cardBorderColor = config?.cardBorderColor || "#E9ECEF";
  const nameColor = config?.nameColor || "#212529";
  const titleColor = config?.titleColor || "#6C757D";
  const departmentColor = config?.departmentColor || "#495057";
  const connectorColor = config?.connectorColor || "#DEE2E6";
  const nameSize = parseInt(config?.nameSize || '14');
  const nameWeight = config?.nameWeight || "500";
  const titleSize = parseInt(config?.titleSize || '12');
  const titleWeight = config?.titleWeight || "400";
  const departmentSize = parseInt(config?.departmentSize || '11');
  const departmentWeight = config?.departmentWeight || "500";
  const cardCornerRadius = config?.cardCornerRadius || "6px";
  const cardPadding = config?.cardPadding || "16px";
  const levelSpacing = parseInt(config?.levelSpacing || '80');
  const siblingSpacing = config?.siblingSpacing || "24px";

  const orgData = {
    id: 'ceo',
    name: 'Sarah Johnson',
    title: 'Chief Executive Officer',
    department: 'Executive',
    reports: [
      {
        id: 'cto',
        name: 'Michael Chen',
        title: 'Chief Technology Officer',
        department: 'Technology',
        reports: [
          { id: 'eng1', name: 'David Park', title: 'Engineering Manager', department: 'Engineering' },
          { id: 'eng2', name: 'Lisa Wang', title: 'Product Manager', department: 'Product' }
        ]
      },
      {
        id: 'cfo',
        name: 'Emily Rodriguez',
        title: 'Chief Financial Officer',
        department: 'Finance',
        reports: [
          { id: 'fin1', name: 'James Smith', title: 'Controller', department: 'Accounting' },
          { id: 'fin2', name: 'Anna Lee', title: 'Treasurer', department: 'Treasury' }
        ]
      },
      {
        id: 'coo',
        name: 'Robert Taylor',
        title: 'Chief Operating Officer',
        department: 'Operations',
        reports: [
          { id: 'ops1', name: 'Maria Garcia', title: 'Operations Manager', department: 'Operations' },
          { id: 'ops2', name: 'Tom Wilson', title: 'HR Manager', department: 'Human Resources' }
        ]
      }
    ]
  };

  React.useEffect(() => {
    if (expandAllDefault) {
      const allIds = new Set();
      const collectIds = (node) => {
        allIds.add(node.id);
        if (node.reports) {
          node.reports.forEach(collectIds);
        }
      };
      collectIds(orgData);
      setExpandedNodes(allIds);
    }
  }, [expandAllDefault]);

  const toggleNode = (nodeId) => {
    setExpandedNodes(prev => {
      const newSet = new Set(prev);
      if (newSet.has(nodeId)) {
        newSet.delete(nodeId);
      } else {
        newSet.add(nodeId);
      }
      return newSet;
    });
  };

  const getInitials = (name) => {
    return name.split(' ').map(n => n[0]).join('');
  };

  const renderCard = (person, hasReports) => {
    const isExpanded = expandedNodes.has(person.id);

    return (
      <div
        style={{
          backgroundColor: cardBackgroundColor,
          border: `1px solid ${cardBorderColor}`,
          borderRadius: cardCornerRadius,
          padding: cardPadding,
          minWidth: '200px',
          cursor: hasReports ? 'pointer' : 'default',
          transition: 'all 0.25s ease-out',
          boxShadow: '0 1px 3px rgba(0,0,0,0.06)',
          position: 'relative'
        }}
        onClick={() => hasReports && toggleNode(person.id)}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          {showPhotos && (
            <div style={{
              width: '40px',
              height: '40px',
              borderRadius: '50%',
              backgroundColor: cardBorderColor,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontSize: '14px',
              fontWeight: '500',
              color: nameColor,
              flexShrink: 0
            }}>
              {getInitials(person.name)}
            </div>
          )}

          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{
              fontSize: nameSize + 'px',
              fontWeight: nameWeight,
              color: nameColor,
              marginBottom: '2px',
              whiteSpace: 'nowrap',
              overflow: 'hidden',
              textOverflow: 'ellipsis'
            }}>
              {person.name}
            </div>
            <div style={{
              fontSize: titleSize + 'px',
              fontWeight: titleWeight,
              color: titleColor,
              whiteSpace: 'nowrap',
              overflow: 'hidden',
              textOverflow: 'ellipsis'
            }}>
              {person.title}
            </div>
            {showDepartments && (
              <div style={{
                fontSize: departmentSize + 'px',
                fontWeight: departmentWeight,
                color: departmentColor,
                marginTop: '4px',
                textTransform: 'uppercase',
                letterSpacing: '0.05em'
              }}>
                {person.department}
              </div>
            )}
          </div>

          {hasReports && (
            <div style={{
              fontSize: '10px',
              opacity: 0.7,
              transform: isExpanded ? 'rotate(180deg)' : 'rotate(0)',
              transition: 'transform 0.25s ease-out',
              flexShrink: 0
            }}>
              ▼
            </div>
          )}
        </div>
      </div>
    );
  };

  const renderNode = (person, depth = 0) => {
    const hasReports = person.reports && person.reports.length > 0;
    const isExpanded = expandedNodes.has(person.id);

    return (
      <div key={person.id} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
        {renderCard(person, hasReports)}

        {hasReports && isExpanded && (
          <div style={{
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            marginTop: levelSpacing + 'px',
            position: 'relative',
            opacity: 1,
            animation: 'fadeIn 0.4s ease-out'
