            <div style={{
              width: '2px',
              height: (levelSpacing / 2) + 'px',
              backgroundColor: connectorColor,
              position: 'absolute',
              top: `-${levelSpacing}px`,
              left: '50%',
              transform: 'translateX(-50%)'
            }} />

            <div style={{
              display: 'flex',
              gap: siblingSpacing,
              justifyContent: 'center',
              position: 'relative'
            }}>
              {person.reports.length > 1 && (
                <div style={{
                  position: 'absolute',
                  top: `-${levelSpacing / 2}px`,
                  left: 0,
                  right: 0,
                  height: '2px',
                  backgroundColor: connectorColor
                }} />
              )}

              {person.reports.map((report, index) => (
                <div key={report.id} style={{ position: 'relative' }}>
                  <div style={{
                    width: '2px',
                    height: (levelSpacing / 2) + 'px',
                    backgroundColor: connectorColor,
                    position: 'absolute',
                    top: `-${levelSpacing / 2}px`,
                    left: '50%',
                    transform: 'translateX(-50%)'
                  }} />
                  {renderNode(report, depth + 1)}
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    );
  };

  return (
    <div 
      className="org-chart-container"
      style={{
        width: '100%',
        minHeight: '600px',
        backgroundColor,
        padding: '48px 24px',
        overflow: 'auto'
      }}
    >
      <style>{`
        @keyframes fadeIn {
          from {
            opacity: 0;
            transform: translateY(-15px);
          }
          to {
            opacity: 1;
            transform: translateY(0);
          }
        }
      `}</style>

      <div style={{ display: 'flex', justifyContent: 'center' }}>
        {renderNode(orgData)}
      </div>
    </div>
  );
}

